// Copies the sample books into public/samples (the showcase book is generated by make-showcase).
import { copyFileSync, mkdirSync } from 'node:fs';
const out = new URL('../public/samples/', import.meta.url);
mkdirSync(out, { recursive: true });
for (const f of ['all-features', 'lab']) copyFileSync(new URL(`../../../conformance/valid/${f}.chalk`, import.meta.url), new URL(`${f}.chalk`, out));
console.log('samples → public/samples');
